package com.tapeverify.copilot.config;
import com.tapeverify.copilot.entity.AppUser; import com.tapeverify.copilot.entity.Role; import com.tapeverify.copilot.repository.UserRepository; import java.time.LocalDateTime; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class BootstrapAdminConfig { @Bean CommandLineRunner bootstrapAdmin(UserRepository users,PasswordEncoder encoder,@Value("${app.bootstrap-admin.username:}") String username,@Value("${app.bootstrap-admin.password:}") String password){return args->{if(username!=null&&!username.isBlank()&&password!=null&&!password.isBlank()&&users.findByUsername(username).isEmpty())users.save(AppUser.builder().username(username.trim()).passwordHash(encoder.encode(password)).role(Role.ADMIN).active(true).createdAt(LocalDateTime.now()).build());};} }
